    lossG.appendChild(kitNote);

    /* ② 课程：台阶图 */
    var stairG = group(s);
    stairG.appendChild(svgRich(30, 118, '课程学习：一次往后滚 $T_{cur}$ 个 code，从 ' + CUR_START + ' 加到 ' + CUR_END, { size: 10, w: 380, cls: 'demo-x-ink2' }));
    hline(stairG, S9_X0 - 4, s9Y(0), S9_X0 - 4, s9Y(50), C_BORDER, 1.2);
    hline(stairG, S9_X0 - 4, s9Y(0), S9_X1, s9Y(0), C_BORDER, 1.2);
    [CUR_START, CUR_END].forEach(function (k) {
      hline(stairG, S9_X0 - 4, s9Y(k), S9_X1, s9Y(k), C_GRID, 1, '3 3');
      stairG.appendChild(svgText(S9_X0 - 8, s9Y(k) + 3, k + ' = ' + s9Sec(k) + ' s', 'demo-x-mono', 9, 'end'));
    });
    stairG.appendChild(svgText(s9X(1.5), 293, '1', 'demo-x-mono demo-x-mut', 8.5, 'middle'));
    stairG.appendChild(svgText(s9X(N_STAGES + 0.5), 293, String(N_STAGES), 'demo-x-mono demo-x-mut', 8.5, 'middle'));
    var stageT = svgText(s9X(N_STAGES / 2 + 1), 293, '', 'demo-x-ink2', 9, 'middle');
    stairG.appendChild(stageT);
    /* 一上来就滚 49 步：误差越滚越大（示意，红色抖动越往右越大） */
