    var coinRim = paint(svgEl('circle', { cx: 0, cy: 0, r: COIN.r - 4, fill: 'none', 'stroke-width': 1 }), null, 'var(--demo-surface)');
    coinRim.style.opacity = 0.6;
    coinG.appendChild(coinRim);
