    var RB = { x: 126, y: 384, w: 294, h: 16 };
    var ratioG = group(tfG);
    var rGood = hbar(ratioG, RB.x, RB.y, RB.h, C_GOOD, 0.9);
    var rSelf = hbar(ratioG, RB.x + RB.w * P_TF, RB.y, RB.h, C_ACCENT, 0.9);
