    rSelfT.setTone('var(--demo-surface)');
    ratioG.appendChild(rGoodT);
    ratioG.appendChild(rSelfT);

    /* ⑤ c^0 = E(平均姿态)，解码器跟着微调 */
    var c0G = group(s);
    rectBox(c0G, 452, 306, 318, 106, C_BORDER, C_SURFACE);
