    lrG.appendChild(paint(svgText(762, 374, s9Lr(LR_DEC), 'demo-x-mono', 9.5, 'end'), C_GOOD));
    var lrDecBar = hbar(lrG, 656, 380, 6, C_GOOD, 0.9);
