      drawOn(errPath, seg(t, 3.1, 4.1));
      setOpacity(errG, seg(t, 3.1, 3.3) * (1 - seg(t, 4.6, 5.0)));
      var drawU = ease(seg(t, 4.4, 6.6));
      var front = s9Walk(drawU);
