    var inner = svgEl('svg', { x: FIG.x + FIG.pad, y: FIG.y + FIG.pad, width: IW, height: IH, viewBox: [S10_CROP.x, S10_CROP.y, S10_CROP.w, S10_CROP.h].join(' '), preserveAspectRatio: 'xMidYMid meet' });
