    var annM = svgRich(30, 218, '**读动作**：$E$ → snippet code → 双向 GRU（' + S10_EXT_HID + '）→ $m$', { size: 9, w: 234, cls: 'demo-x-acc' });
    figTop.appendChild(annM);
