      setLine(lead0, p0[0] + 4, p0[1] - 4, LAB_XY[0][0] - 3, LAB_XY[0][1] - 4);
      setOpacity(lead0, seg(t, 4.4, 4.8));
      /* 不配对、在圈里：D = 6，往外推 */
      var p1 = pAt(ex[1].c.d, S10_ANG[1]);
