    var vp = svgEl('svg', { x: x + pad, y: y + pad, width: (w - 2 * pad).toFixed(1), height: (h - 2 * pad).toFixed(1), viewBox: '0 0 ' + S11_F4.cropW + ' ' + S11_F4.H, preserveAspectRatio: 'xMinYMin meet', overflow: 'hidden' });
