    var arc = paint(svgEl('circle', { cx: RING.x, cy: RING.y, r: RING.r, fill: 'none', 'stroke-width': 9, transform: 'rotate(-90 ' + RING.x + ' ' + RING.y + ')' }), null, C_GOOD);
