      setOpacity(usText, seg(t, 11.6, 12.0));
      setOpacity(usNote, seg(t, 12.3, 12.7));

      /* ⑤ 13.5–16 s：KIT-ML 三根小柱 */
      setOpacity(kitG, seg(t, 13.6, 14.0));
